('home', 'stats', '', '', '', '', '', '', '', '', '["15+|Years of Experience","10K+|Happy Patients","25+|Expert Therapists","40+|Natural Therapies"]'),
('home', 'about_intro', 'About Chitrawan', 'Healing Naturally, Living Fully', 'Chitrawan Nature Cure Hospital is a holistic healthcare destination committed to promoting natural healing and preventive healthcare. Our peaceful environment, expert practitioners, and evidence-based therapies help patients restore balance and improve their quality of life.', 'Since 2010|Healing with care & compassion', '/wellness/public/uploads/photos/photo-1545205597-3d9d02c29597.jpg', '', '/about', 'More About Us', '["Treating the root cause, not just symptoms","Personalized plans for every patient","Traditional wisdom meets modern science","A calm, natural environment for healing"]'),
